async function linkSelection(ids){if(!ids.length)throw new Error('Select a note first.');showModal('Use your existing cards.','This adds a local project link, not another Anki note.',`<label class="field">Project<select id="ws-link-project">${S.state.projects.map(p=>option(p.id,p.title,S.project)).join('')}</select></label><p class="fine" style="margin-top:15px">${ids.length} original notes will be connected. Their fields, card IDs, and scheduling stay unchanged. A selected source passage is attached only when it belongs to this project.</p>`,B('close-modal','Cancel','','small')+B('confirm-modal','Link original notes','source','primary small'),async()=>{const pid=$('#ws-link-project').value;if(!pid)throw new Error('Create a project first.');const src=S.source?.source.project_id===pid?{source_id:S.source.source.id,version_id:S.source.version.id,page:S.page,quote:S.selection}:{};for(const id of ids)await request('link',{note_id:id,project_id:pid,...src});closeModal();await refreshState();render();toast(`${ids.length} original note${ids.length===1?'':'s'} linked. No duplicate cards created.`);});}
async function confirmSource(lid){const link=S.state.links.find(l=>l.id===lid);if(!link)throw new Error('Refresh this note’s source links.');const d=await request('source',{id:link.source_id});showModal('Recheck the source link.','The note’s actual content is not edited by confirming this reference.',`<p class="fine"><strong>${E(d.source.title)}</strong> · new edition ${d.version.ordinal}</p><label class="field" style="margin-top:15px">Revised page<select id="ws-revised-page">${d.version.pages.map(p=>option(p.page,'Page '+p.page,Math.min(link.page,d.version.pages.length))).join('')}</select></label><div id="ws-revised-text" class="notice pre" style="max-height:270px;overflow:auto;margin-top:15px">${E(d.version.pages[Math.min(link.page,d.version.pages.length)-1].text)}</div><label class="field" style="margin-top:15px">Revised supporting passage<textarea id="ws-revised-quote">${E(link.quote||'')}</textarea></label><label class="check" style="margin-top:15px"><input type="checkbox" id="ws-source-confirmed"><span>I checked the original note against this revised page. Its question and answer still hold.</span></label>`,B('close-modal','Cancel','','small')+B('confirm-modal','Update source reference','check','primary small'),async()=>{if(!$('#ws-source-confirmed').checked)throw new Error('Check the original note against the revised source before confirming.');await request('source_confirm',{link_id:lid,page:Number($('#ws-revised-page').value),quote:$('#ws-revised-quote').value,approved:true});closeModal();await refreshState();toast('Source reference updated. The Anki note’s fields are unchanged.');});$('#ws-revised-page').addEventListener('change',e=>{$('#ws-revised-text').textContent=d.version.pages[Number(e.target.value)-1].text;});}
let settingsChain=Promise.resolve();
